//go:build linux

package app

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/berryhill/aegis/internal/credentials"
	credentialbolt "github.com/berryhill/aegis/internal/credentials/bbolt"
	"github.com/berryhill/aegis/internal/credentials/broker"
)

// Exercise the actual owning service with encrypted custody, not interpretation
// fixtures. Values are generated by brokerAuthorizedService and never logged.
func TestCredentialSkillBrokerDenialsAndNondisclosure(t *testing.T) {
	for _, name := range []string{"wrong-recipient-uid", "wrong-recipient-gid", "wrong-recipient-process", "wrong-repository", "unbound", "malformed", "stale", "replay", "revoked"} {
		t.Run(name, func(t *testing.T) {
			s, token, canary, authority := brokerAuthorizedService(t)
			ctx := context.Background()
			if name == "unbound" {
				key := make([]byte, 32)
				if _, err := rand.Read(key); err != nil {
					t.Fatal("synthetic custody generation failed")
				}
				custodian := &brokerTestCustodian{key: key}
				directory := filepath.Join(t.TempDir(), "authority")
				if err := os.Mkdir(directory, 0700); err != nil {
					t.Fatal("private authority directory failed")
				}
				repository, err := credentialbolt.Open(ctx, filepath.Join(directory, "unbound.db"), "deployment-test", custodian)
				if err != nil {
					t.Fatal("unbound authority open failed")
				}
				authority = credentials.NewAuthority(repository, custodian)
				t.Cleanup(func() { _ = authority.Close() })
				if _, err := authority.Create(ctx, "local/api", "api-token", "principal-1", []byte(canary)); err != nil {
					t.Fatal("unbound record creation failed")
				}
				s.CredentialAuthority = authority
			}
			peer := broker.Peer{PID: int32(os.Getpid()), UID: uint32(os.Getuid()), GID: uint32(os.Getgid())}
			request := validBrokerRequest(token, s.Now())
			// Positive readback must stay useful without exposing either kind of secret.
			records, err := authority.List(ctx, "local/api", 1)
			if err != nil || len(records) != 1 || records[0].CurrentVersion != 1 || records[0].Status != "active" {
				t.Fatal("metadata readback failed")
			}
			metadata, err := authority.Metadata(ctx, records[0].ID)
			if err != nil || metadata.ID != records[0].ID || metadata.Reference != "local/api" {
				t.Fatal("exact metadata readback failed")
			}
			var successfulResult broker.Result
			switch name {
			case "wrong-recipient-uid":
				peer.UID++
			case "wrong-recipient-gid":
				peer.GID++
			case "wrong-recipient-process":
				peer.PID = 1
			case "wrong-repository":
				request.Repository = "not-approved"

			case "malformed":
				request.RequestID = "invalid"
			case "stale":
				request.Deadline = s.Now()
			case "revoked":
				if err := authority.Revoke(ctx, metadata.ID, 1, "test-revocation"); err != nil {
					t.Fatal("revoke failed")
				}
			case "replay":
				result, err := s.ExecuteBroker(ctx, peer, request, func(_ context.Context, value []byte, grant broker.Grant) (broker.Result, error) {
					if !bytes.Equal(value, []byte(canary)) || grant.RecordID != metadata.ID || grant.Version != 1 {
						t.Fatal("incorrect credential resolution")
					}
					return broker.Result{StatusCode: 200, Outcome: "credential_applied", Repository: broker.Repository{Owner: request.Owner, Name: request.Repository}}, nil
				})
				if err != nil || result.Repository.Name != request.Repository {
					t.Fatal("successful typed result missing")
				}
				successfulResult = result
			}
			called := false
			result, err := s.ExecuteBroker(ctx, peer, request, func(context.Context, []byte, broker.Grant) (broker.Result, error) {
				called = true
				return broker.Result{}, nil
			})
			if !errors.Is(err, ErrDenied) || called {
				t.Fatal("denial did not precede credential use")
			}
			events, auditErr := s.Store.AuditEvents()
			if auditErr != nil {
				t.Fatal("audit readback failed")
			}
			wantReason := map[string]string{
				"wrong-recipient-uid": "peer_identity_mismatch", "wrong-recipient-gid": "peer_identity_mismatch",
				"wrong-recipient-process": "runtime_process_identity_lost", "wrong-repository": "repository_denied",
				"unbound": "credential_resolution_or_audit_denied", "revoked": "credential_resolution_or_audit_denied",
				"malformed": "request_freshness_invalid", "stale": "request_expired_or_unbounded", "replay": "request_replayed",
			}[name]
			if len(events) == 0 || events[len(events)-1].Type != "credential_broker" || events[len(events)-1].Outcome != "deny" || events[len(events)-1].Reason != wantReason {
				t.Fatal("distinct authoritative denial audit missing")
			}
			output, marshalErr := json.Marshal(struct {
				Metadata         any
				Result           any
				SuccessfulResult any
				Audit            any
				Diagnostic       string
			}{metadata, result, successfulResult, events, fmt.Sprint(err)})
			if marshalErr != nil {
				t.Fatal("metadata encoding failed")
			}
			assertNoMaterial := func(data []byte) {
				t.Helper()
				if bytes.Contains(data, []byte(canary)) || bytes.Contains(data, []byte(token)) {
					t.Fatal("credential or capability escaped into ordinary artifacts")
				}
			}
			assertNoMaterial(output)
			if err := authority.Backup(ctx, filepath.Join(s.Store.Root(), "credential-skill.backup")); err != nil {
				t.Fatal("ciphertext backup failed")
			}
			// Scan the ciphertext backup and ordinary Store.Root artifacts. The
			// fixture's original bbolt authority is outside Store.Root and its KEK
			// is memory-only; neither is claimed as covered by this filesystem scan.
			if err := filepath.WalkDir(s.Store.Root(), func(path string, entry os.DirEntry, walkErr error) error {
				if walkErr != nil {
					return walkErr
				}
				if entry.IsDir() {
					// Engine files are not ordinary retained artifacts. Badger may
					// preallocate multi-GiB sparse logs; inspect canonical audit via
					// AuditEvents above, not unrelated engine allocation here.
					if path != s.Store.Root() && entry.Name() == "persistence" {
						return filepath.SkipDir
					}
					return nil
				}
				data, err := os.ReadFile(path)
				if err != nil {
					return err
				}
				assertNoMaterial(data)
				return nil
			}); err != nil {
				t.Fatal("retained-artifact scan failed")
			}
			for _, file := range []string{"cmdline", "environ"} {
				data, err := os.ReadFile(filepath.Join("/proc/self", file))
				if err != nil {
					t.Fatal("process boundary inspection failed")
				}
				assertNoMaterial(data)
			}
		})
	}
}
